    best=(0,0)
    for r,e,a in pts:
        if r>0.05 and e<-0.9 and r>best[0]: best=(r,a)
    return best

def comp_of(pts):
    # returns at horizon, plausible companion range
    hits=[(r,a) for r,e,a in pts if r>0.35 and r<0.85 and -0.05<=e<=0.25]
    if not hits: return (0,0,0)
    mx=max(hits)
